/**
 * Row and section shapes for the computed chart datasets.
 *
 * The three datasets in this folder do arithmetic rather than read a catalog, and each one
 * shapes its output into rows a table or a chart can render directly. Those shapes live here,
 * beside one another, so a page that lays out more than one of them names a single type per
 * dataset instead of re-declaring the columns next to every builder that returns them.
 */

export interface GoldBotDeathWaveRow {
  gbCooldownSec: number
  deathWaveOffsetSec: number
  syncPercent: number
}

export interface GoldenTowerIncomeComparisonRow {
  duration: number
  gtPlus1: string
  gtPlus2: string
  gtPlus3: string
  gtPlus4: string
  gtPlus5: string
  gtPlus6: string
  gtPlus7: string
  gtPlus8: string
  gtPlus9: string
  gtPlus10: string
}

export interface GoldenTowerMilestoneUnlockRow {
  tier: string
  track: string
  wave: number
  reward: string
  kind: string
}

export interface UwPlusUpgradeTier {
  value: string
  cost: string
}

export interface UwPlusUpgradeRow {
  icon: string
  name: string
  arrow: string
  next: string
  desc: string
  tiers: Record<number, UwPlusUpgradeTier>
}

export interface UwPlusUpgradeSection {
  title: string
  total: string
  upgrades: UwPlusUpgradeRow[]
}
